"""Brute-force solvers and randomized/exhaustive tests for the reduction."""

from __future__ import annotations

import itertools
import random

from problems import HamiltonianCycle, HamiltonianPath
from reduce import reduce


# ---------------------------------------------------------------- solvers

def has_hamiltonian_cycle(instance) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    if n <= 2:
        return False
    adj = [[False] * n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = adj[v][u] = True
    # fix vertex 0 as the start to cut permutations by a factor of n
    for perm in itertools.permutations(range(1, n)):
        seq = (0,) + perm
        if all(adj[seq[i]][seq[i + 1]] for i in range(n - 1)) and adj[seq[-1]][seq[0]]:
            return True
    return False


def has_hamiltonian_path(instance) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    if n == 0:
        return False
    if n == 1:
        return True
    adj = [[False] * n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = adj[v][u] = True
    for perm in itertools.permutations(range(n)):
        if all(adj[perm[i]][perm[i + 1]] for i in range(n - 1)):
            return True
    return False


# ---------------------------------------------------------------- helpers

def all_graphs(n: int):
    """All simple undirected graphs on n labelled vertices."""
    pairs = [(u, v) for u in range(n) for v in range(u + 1, n)]
    for mask in range(1 << len(pairs)):
        edges = [list(pairs[i]) for i in range(len(pairs)) if (mask >> i) & 1]
        yield {"n": n, "edges": edges}


def random_graph(n: int, p: float, rng: random.Random):
    edges = []
    for u in range(n):
        for v in range(u + 1, n):
            if rng.random() < p:
                edges.append([u, v])
    return {"n": n, "edges": edges}


def main() -> int:
    tests_run = 0
    tests_passed = 0

    def check(instance):
        nonlocal tests_run, tests_passed
        tests_run += 1
        HamiltonianCycle.validate(instance)
        reduced = reduce(instance)
        HamiltonianPath.validate(reduced)
        expected = has_hamiltonian_cycle(instance)
        got = has_hamiltonian_path(reduced)
        assert expected == got, (
            f"mismatch on {instance}: cycle={expected}, reduced={reduced}, path={got}"
        )
        tests_passed += 1

    # exhaustive over all graphs for n = 0..5
    for n in range(0, 6):
        for g in all_graphs(n):
            check(g)

    # random graphs on larger n
    rng = random.Random(12345)
    for _ in range(400):
        n = rng.randint(0, 8)
        p = rng.choice([0.1, 0.2, 0.3, 0.5, 0.7, 0.9])
        check(random_graph(n, p, rng))

    # a few structured cases
    for n in range(3, 9):
        # cycle graph
        check({"n": n, "edges": [[i, (i + 1) % n] for i in range(n)]})
        # path graph (no cycle, has path)
        check({"n": n, "edges": [[i, i + 1] for i in range(n - 1)]})
        # complete graph
        check({"n": n, "edges": [[u, v] for u in range(n) for v in range(u + 1, n)]})
        # empty graph
        check({"n": n, "edges": []})

    print(f"tests_run={tests_run} tests_passed={tests_passed}")
    assert tests_run == tests_passed
    return tests_run


if __name__ == "__main__":
    main()
